import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { MeshoptDecoder } from 'three/addons/libs/meshopt_decoder.module.js';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';

/** Instances are grouped into square cells of this size (frustum culling + LOD per cell). */
const CELL = 100;

/** One entry of public/assets/library.json (generated by tools/assets/library.py). */
export interface AssetEntry {
  id: string;
  category: string;
  title: string;
  sourceUrl: string;
  author: string;
  license: string;
  attribution: string;
  targetHeight: number;
  lodDistances: number[];
  lods: Record<string, { file: string; bytes: number; triangles: number; bounds: [number[], number[]] }>;
}

export interface Placement {
  position: THREE.Vector3;
  yaw: number;
  scale?: number;
}

interface LoadedLod {
  parts: { geometry: THREE.BufferGeometry; material: THREE.Material }[];
}

/**
 * Central runtime asset library: loads GLB models on demand (meshopt + WebP), caches them,
 * normalises their size from the library metadata and builds instanced, LOD-switched
 * meshes per 200 m area. Keeps statistics for the performance monitor.
 */
export class AssetLibrary {
  private entries = new Map<string, AssetEntry>();
  private cache = new Map<string, Promise<LoadedLod>>();
  private readonly loader = new GLTFLoader();
  readonly stats = { assetsLoaded: 0, bytesLoaded: 0, instances: 0 };

  constructor(private readonly baseUrl: string) {
    this.loader.setMeshoptDecoder(MeshoptDecoder);
  }

  async init(): Promise<void> {
    try {
      const res = await fetch(`${this.baseUrl}assets/library.json`);
      if (!res.ok) return;
      const lib = (await res.json()) as { assets: Record<string, AssetEntry> };
      for (const e of Object.values(lib.assets)) this.entries.set(e.id, e);
    } catch {
      /* library optional – procedural fallbacks are used */
    }
  }

  has(id: string): boolean {
    return this.entries.has(id);
  }

  get(id: string): AssetEntry | undefined {
    return this.entries.get(id);
  }

  /** Attribution lines for credits (CC-BY etc.). */
  credits(): string[] {
    return [...this.entries.values()].map((e) => e.attribution);
  }

  /**
   * Creates instanced meshes for all placements, grouped into 200 m cells with a
   * THREE.LOD per cell (lod0 near, lod1 far). Returns the group to add to the scene.
   */
  async instantiate(
    id: string,
    placements: Placement[],
    options: { castShadow?: boolean; collider?: (p: Placement, h: number) => void; cullDistance?: number } = {},
  ): Promise<THREE.Group> {
    const group = new THREE.Group();
    group.name = `asset:${id}`;
    const entry = this.entries.get(id);
    if (!entry || placements.length === 0) return group;
    const [lod0, lod1] = await Promise.all([this.load(entry, 'lod0'), this.load(entry, 'lod1')]);
    const b = entry.lods.lod0.bounds;
    const height = Math.max(b[1][1] - b[0][1], 0.01);
    const norm = entry.targetHeight / height;

    const cells = new Map<string, Placement[]>();
    for (const p of placements) {
      const key = `${Math.floor(p.position.x / CELL)},${Math.floor(p.position.z / CELL)}`;
      (cells.get(key) ?? cells.set(key, []).get(key)!).push(p);
    }
    const m = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const up = new THREE.Vector3(0, 1, 0);
    for (const list of cells.values()) {
      const center = list.reduce((c, p) => c.add(p.position), new THREE.Vector3()).divideScalar(list.length);
      const lod = new THREE.LOD();
      lod.position.copy(center);
      const build = (src: LoadedLod, shadows: boolean) => {
        const holder = new THREE.Group();
        for (const part of src.parts) {
          const mesh = new THREE.InstancedMesh(part.geometry, part.material, list.length);
          list.forEach((p, i) => {
            const s = norm * (p.scale ?? 1);
            // ground the model: its lowest point sits on the placement height
            const pos = p.position.clone().sub(center);
            pos.y -= b[0][1] * s;
            m.compose(pos, q.setFromAxisAngle(up, p.yaw), new THREE.Vector3(s, s, s));
            mesh.setMatrixAt(i, m);
          });
          mesh.castShadow = shadows && (options.castShadow ?? true);
          mesh.receiveShadow = true;
          mesh.computeBoundingSphere();
          holder.add(mesh);
        }
        return holder;
      };
      // Distances are measured to the cell centre: add half the cell diagonal.
      const slack = CELL * 0.5;
      lod.addLevel(build(lod0, true), 0);
      // Far level: no shadow casting (sub-pixel shadows, big saving in the shadow pass).
      lod.addLevel(build(lod1, false), (entry.lodDistances[1] ?? 45) + slack * 0.5);
      lod.addLevel(new THREE.Object3D(), (options.cullDistance ?? 200) + slack);
      group.add(lod);
      for (const p of list) options.collider?.(p, entry.targetHeight * (p.scale ?? 1));
    }
    this.stats.instances += placements.length;
    return group;
  }

  private load(entry: AssetEntry, lod: string): Promise<LoadedLod> {
    const key = `${entry.id}/${lod}`;
    let p = this.cache.get(key);
    if (!p) {
      const info = entry.lods[lod] ?? entry.lods.lod0;
      p = this.loader.loadAsync(`${this.baseUrl}assets/${info.file}`).then((gltf) => {
        this.stats.assetsLoaded++;
        this.stats.bytesLoaded += info.bytes;
        // One part per material: merge all primitives that share it (fewer draw calls).
        const byMaterial = new Map<THREE.Material, THREE.BufferGeometry[]>();
        gltf.scene.updateMatrixWorld(true);
        gltf.scene.traverse((o) => {
          const mesh = o as THREE.Mesh;
          if (!mesh.isMesh) return;
          const geometry = mesh.geometry.clone().applyMatrix4(mesh.matrixWorld);
          const material = mesh.material as THREE.Material;
          (byMaterial.get(material) ?? byMaterial.set(material, []).get(material)!).push(geometry);
        });
        const parts: LoadedLod['parts'] = [];
        for (const [material, geos] of byMaterial) {
          const merged = geos.length > 1 ? mergeGeometries(geos) : geos[0];
          if (merged) parts.push({ geometry: merged, material });
          else for (const g of geos) parts.push({ geometry: g, material });
        }
        return { parts };
      });
      this.cache.set(key, p);
    }
    return p;
  }
}
